import math

# Invented practice data: replace names, labels, all scores, and K.
# Same feature order for every film: 愛情、親情 / 動作 / 動畫.
query_name = '待分類電影'
query = [2, 3, 8]
movies = [
    ['電影甲', [2, 4, 8], '動畫片'],
    ['電影乙', [3, 3, 8], '動畫片'],
    ['電影丙', [2, 3, 6], '動作片'],
    ['電影丁', [5, 3, 8], '愛情片'],
    ['電影戊', [2, 7, 8], '動作片'],
]
K = 4
if not 1 <= K <= len(movies):
    raise ValueError('K 必須介於 1 與候選電影數量之間')
rows = []
for name, features, genre in movies:
    if len(features) != len(query):
        raise ValueError('特徵數量必須一致')
    squared = 0
    for j in range(len(query)):
        squared += (features[j]-query[j])**2
    rows.append([name, math.sqrt(squared), features, genre, sum(features)])

# Stable bubble sort: compare computed distances, never hard-code the order.
for i in range(len(rows)-1):
    for j in range(len(rows)-1-i):
        if rows[j][1] > rows[j+1][1]:
            rows[j], rows[j+1] = rows[j+1], rows[j]

print('全部電影（歐幾里得距離由小到大）：')
for name, distance, features, genre, total in rows:
    print(f'{name}，距離：{distance:.4f}，特徵：{features}，類型：{genre}，特徵總和：{total}')
nearest = rows[:K]
print(f'最近的 {K} 部電影：')
for name, distance, features, genre, total in nearest:
    print(f'{name}，距離：{distance:.4f}，類型：{genre}')

votes = {}
for name, features, genre in movies:
    votes[genre] = 0
for row in nearest:
    votes[row[3]] += 1
print('各類型票數：')
for genre, count in votes.items():
    print(f'{genre}：{count} 票')
max_votes = max(votes.values())
winners = []
for genre, count in votes.items():
    if count == max_votes:
        winners.append(genre)
if len(winners) == 1:
    print(f'分類結果：{winners[0]}，{max_votes} 票')
else:
    print(f'平票：{"、".join(winners)}，各 {max_votes} 票；需依題目規定處理')

